import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, vec2, sin, fract, dot, uniform, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Color, DirectionalLight, Texture } = THREE;

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? { text: 'Collection', typography: { fontSize: 96 } };
  const headlineText = (headlineItem.text ?? 'Collection').replace(/[^\x00-\x7F]/g, '');

  const root = new Group();
  root.name = 'collection-title';

  // ---- title plate (engineered gradient, machined-metal-lite surface, subtle grain) ----
  const plateW = 4.6;
  const plateH = 1.3;
  const plateGeo = new PlaneGeometry(plateW, plateH, 1, 1);

  const uvNode = uv();
  const inkC = uniform(new Color(colors.ink));
  const surfaceC = uniform(new Color(colors.surface));
  const gradient = mix(surfaceC, inkC, uvNode.y);

  // hash-based grain (TSL nodes only, no raw shader strings)
  const grainSeed = fract(sin(dot(uvNode.mul(600.0), vec2(12.9898, 78.233))).mul(43758.5453));
  const grain = grainSeed.sub(0.5).mul(0.035);
  const grainVec = vec3(grain, grain, grain);

  // placeholder texture node — value swapped in when the async load resolves
  const placeholderTex = new Texture();
  const texNode = texture(placeholderTex);
  const texturedGradient = gradient.mul(mix(vec3(1, 1, 1), texNode.rgb, 0.22));

  const plateMat = new MeshStandardNodeMaterial();
  plateMat.colorNode = texturedGradient.add(grainVec);
  plateMat.roughness = 0.58;
  plateMat.metalness = 0.4;
  plateMat.clearcoat = 0.12;
  plateMat.transparent = false;

  const plateMesh = new Mesh(plateGeo, plateMat);
  plateMesh.position.set(0, 0, -0.2);
  root.add(plateMesh);

  let loadedTexture = null;
  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      loadedTexture = tex;
      texNode.value = tex;
      plateMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- accent underline (single accent element, <=10% of frame) ----
  const accentGeo = new PlaneGeometry(1.4, 0.045, 1, 1);
  const accentMat = new MeshStandardNodeMaterial();
  const accentColorU = uniform(new Color(colors.accent));
  accentMat.colorNode = vec3(accentColorU);
  accentMat.emissiveNode = vec3(accentColorU).mul(0.9);
  accentMat.roughness = 0.5;
  accentMat.metalness = 0.2;
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(0, -0.48, -0.08);
  root.add(accentMesh);

  // ---- rim light local to this node (product-shot lighting, capped intensity) ----
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.55);
  rimLight.position.set(-1.5, 0.6, 1.2);
  root.add(rimLight);

  // ---- headline text (brightest element on this plate) ----
  const fontSize = headlineItem.typography?.fontSize ?? 96;
  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 1,
  });
  headline.position.set(0, 0.02, 0.06);
  root.add(headline);

  // ---- entrance motion: weighted-settle, no idle perpetual motion (static composition) ----
  root.scale.set(0.96, 0.96, 0.96);
  root.position.y += 0.15;
  const tl = gsap.timeline();
  tl.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  }, 0);
  tl.to(root.position, {
    y: root.position.y - 0.15,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);
  tl.fromTo(headline, { userData: {} }, {
    duration: 0.01,
  }, 0); // placeholder keyframe, no-op safe-guard for headline ref retention

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    plateGeo.dispose();
    plateMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    placeholderTex.dispose();
    if (loadedTexture && loadedTexture.dispose) loadedTexture.dispose();
    if (headline?.geometry) headline.geometry.dispose();
    if (headline?.material) headline.material.dispose();
  };

  return root;
}
